#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import shutil

root=Path.cwd(); public=root/'public'
if not (root/'server.js').exists() or not public.exists(): raise SystemExit('ERREUR: lance depuis omnipay-bj')
stamp=datetime.now().strftime('%Y%m%d-%H%M%S')
for n in ['index.html','omnipay-v2.css','omnipay-v2.js']:
 p=public/n
 if p.exists(): shutil.copy2(p,public/f'{n}.{stamp}.bak')

